-- Generated by scripts/build-ai-legacy-transition-catalog.ts.
-- Install core and both matching runtimes before this activation.
begin;
do $legacy_transition_catalog$
declare contract jsonb:=$legacy_transition_contract${
  "name": "transition_legacy_drawing",
  "description": "Prepare a saved older drawing for construction-driven correction. Read its exact Artifact ID/revision and current selected solution first. The SERVER copies its geometry and parameter graph; never recreate dimensions or IDs. With construction_id:null supply explicit current catalog materials, typed joint choices and open questions. null means evidence is missing and returns all gaps without saving; never infer catalog pins or joints from appearance. A saved graph is required to create; if absent establish a matching construction through the ordinary construction tools and reuse its exact ID/revision with materials/joints/open_questions:null. Reuse requires identical geometry, stable IDs and existing parameter/source pins. Already prepared returns that existing checkpoint without a duplicate. Check the receipt/readback; then change its parameter IDs, check_construction_draft and pass the ORIGINAL drawing Artifact ID and exact construction_revision to design_project_cad. This operation prepares a construction only, preserves drawing history and does not render or deliver a drawing.",
  "parameters": {
    "type": "object",
    "additionalProperties": false,
    "properties": {
      "key": {
        "type": "string",
        "pattern": "^[A-Za-z0-9_-]{1,80}$"
      },
      "record_id": {
        "type": "string",
        "format": "uuid"
      },
      "expected_revision": {
        "type": "integer",
        "minimum": 1,
        "maximum": 999999999
      },
      "target_revision": {
        "type": "integer",
        "minimum": 1,
        "maximum": 999999999
      },
      "construction_id": {
        "anyOf": [
          {
            "type": "string",
            "format": "uuid"
          },
          {
            "type": "null"
          }
        ]
      },
      "construction_revision": {
        "anyOf": [
          {
            "type": "integer",
            "minimum": 1,
            "maximum": 999999999
          },
          {
            "type": "null"
          }
        ]
      },
      "materials": {
        "anyOf": [
          {
            "type": "array",
            "minItems": 1,
            "maxItems": 128,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "definition_id": {
                  "type": "string",
                  "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                },
                "material_id": {
                  "type": "string",
                  "format": "uuid"
                },
                "material_revision": {
                  "type": "integer",
                  "minimum": 1,
                  "maximum": 999999999
                },
                "part_id": {
                  "anyOf": [
                    {
                      "type": "string",
                      "format": "uuid"
                    },
                    {
                      "type": "null"
                    }
                  ]
                },
                "part_revision": {
                  "anyOf": [
                    {
                      "type": "integer",
                      "minimum": 1,
                      "maximum": 999999999
                    },
                    {
                      "type": "null"
                    }
                  ]
                }
              },
              "required": [
                "definition_id",
                "material_id",
                "material_revision",
                "part_id",
                "part_revision"
              ]
            }
          },
          {
            "type": "null"
          }
        ]
      },
      "joints": {
        "anyOf": [
          {
            "type": "array",
            "maxItems": 1024,
            "items": {
              "type": "object",
              "additionalProperties": false,
              "properties": {
                "id": {
                  "type": "string",
                  "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                },
                "method": {
                  "type": "string",
                  "enum": [
                    "screwed_butt",
                    "glued_butt",
                    "dowel",
                    "bolted",
                    "unresolved"
                  ]
                },
                "first": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "instance_id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
                    "face": {
                      "type": "string",
                      "enum": [
                        "x_min",
                        "x_max",
                        "y_min",
                        "y_max",
                        "z_min",
                        "z_max"
                      ]
                    }
                  },
                  "required": [
                    "instance_id",
                    "face"
                  ]
                },
                "second": {
                  "type": "object",
                  "additionalProperties": false,
                  "properties": {
                    "instance_id": {
                      "type": "string",
                      "pattern": "^[A-Za-z][A-Za-z0-9_.:-]{0,79}$"
                    },
                    "face": {
                      "type": "string",
                      "enum": [
                        "x_min",
                        "x_max",
                        "y_min",
                        "y_max",
                        "z_min",
                        "z_max"
                      ]
                    }
                  },
                  "required": [
                    "instance_id",
                    "face"
                  ]
                },
                "reason": {
                  "type": "string",
                  "minLength": 1,
                  "maxLength": 2000
                }
              },
              "required": [
                "id",
                "method",
                "first",
                "second",
                "reason"
              ]
            }
          },
          {
            "type": "null"
          }
        ]
      },
      "open_questions": {
        "anyOf": [
          {
            "type": "array",
            "maxItems": 39,
            "items": {
              "type": "string",
              "minLength": 1,
              "maxLength": 1000
            }
          },
          {
            "type": "null"
          }
        ]
      },
      "change_note": {
        "type": "string",
        "minLength": 1,
        "maxLength": 1000
      },
      "request_quote": {
        "type": "string",
        "minLength": 1,
        "maxLength": 500
      }
    },
    "required": [
      "key",
      "record_id",
      "expected_revision",
      "target_revision",
      "construction_id",
      "construction_revision",
      "materials",
      "joints",
      "open_questions",
      "change_note",
      "request_quote"
    ]
  }
}$legacy_transition_contract$::jsonb;
 policy jsonb:=$legacy_transition_policy${"name":"transition_legacy_drawing","description":"Prepare an exact older drawing for construction-driven correction without rewriting its history.","how_to":"Read the legacy drawing and current design intent. Server copies its saved geometry and graph. Supply exact catalog material pins and typed joint choices, or reuse a matching existing construction. Null evidence returns all gaps; do not invent pins, joints or parameter roles. Check the saved construction receipt/readback, correct its input IDs and render the original drawing Artifact ID with exact construction_revision. This preparation does not deliver a drawing.","schema_version":1,"always_load":false,"preload_phases":[],"active":true}$legacy_transition_policy$::jsonb;
 prior shared.ai_prompt_versions; prompt_uuid uuid; version_uuid uuid; next_version integer; definition jsonb; activation jsonb:='{}'; manual jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended('ai_catalog:bob',0));
 if exists(select 1 from shared.ai_prompts where app='bob' and prompt_key='tools.transition_legacy_drawing') then raise exception 'legacy_transition_already_published'; end if;
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='tools.save_construction_draft';
 if not found then raise exception 'legacy_transition_template_missing'; end if;
 insert into shared.ai_prompts(app,prompt_key,label,description,content,flow,definition_kind) values('bob','tools.transition_legacy_drawing',policy->>'description',policy->>'description','','','tool_contract') returning id into prompt_uuid;
 definition:=prior.definition||contract||jsonb_build_object('handler',contract->>'name','required_parameters',contract#>'{parameters,required}','optional_parameters','[]'::jsonb,'additional_description',policy->>'how_to');
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prompt_uuid,1,'tool_contract',1,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','legacy-construction-transition'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=jsonb_build_object('tools.transition_legacy_drawing',version_uuid);
 for manual in select value from jsonb_array_elements($legacy_reader_manuals$[{"key":"tools.read_cad_artifact","text":" construction_transition identifies the exact saved checkpoint prepared from this legacy revision; it is provenance, not a drawing delivery. Read its current construction before changes. Keep the original drawing Artifact ID for checked publication."},{"key":"tools.design_project_cad","text":" For a legacy drawing first use transition_legacy_drawing. After its construction receipt/readback, pass the original drawing Artifact ID with exact construction_revision. The server renders its checked checkpoint and advances the same drawing history. A pending transition cannot substitute a changed drawing head or switch construction identity."}]$legacy_reader_manuals$::jsonb) loop
  select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key=manual->>'key' and p.definition_kind='tool_contract';
  if not found then raise exception 'legacy_transition_manual_missing'; end if;
  definition:=prior.definition||jsonb_build_object('additional_description',coalesce(prior.definition->>'additional_description','')||(manual->>'text'));
  select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
  insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
   values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','legacy-construction-transition'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
  activation:=activation||jsonb_build_object(manual->>'key',version_uuid);
 end loop;
 select v.* into prior from shared.ai_prompts p join shared.ai_prompt_versions v on v.id=p.active_version_id where p.app='bob' and p.prompt_key='bob.tools' and p.definition_kind='tool_contract' for update of p;
 if not found then raise exception 'legacy_transition_toolbox_missing'; end if;
 definition:=prior.definition;
 definition:=jsonb_set(definition,'{catalog}',definition->'catalog'||jsonb_build_array(policy));
 definition:=jsonb_set(definition,'{contract_keys}',definition->'contract_keys'||jsonb_build_array('tools.transition_legacy_drawing'));
 definition:=jsonb_set(definition,'{shelves}',(select jsonb_agg(case when shelf->>'label'='Drawings and CAD' then jsonb_set(shelf,'{tools}',shelf->'tools'||jsonb_build_array('transition_legacy_drawing')) else shelf end) from jsonb_array_elements(definition->'shelves') shelf));
 select coalesce(max(version),0)+1 into next_version from shared.ai_prompt_versions where prompt_id=prior.prompt_id;
 insert into shared.ai_prompt_versions(prompt_id,version,definition_kind,definition_format_version,metadata,content,definition,flow,available_variables)
  values(prior.prompt_id,next_version,prior.definition_kind,prior.definition_format_version,(prior.metadata-'seed_version'-'source_revision')||jsonb_build_object('publication','legacy-construction-transition'),prior.content,definition,prior.flow,prior.available_variables) returning id into version_uuid;
 activation:=activation||jsonb_build_object('bob.tools',version_uuid);
 perform shared.activate_ai_catalog('bob',activation);
end $legacy_transition_catalog$;
commit;
